/**
 * Component: Divine Shree Ram Hero Section | Tailwind CSS Responsive UI for Devotional |Hero section |Hero
 * Author: @rajesh-pandey (https://tailwindflex.com/@rajesh-pandey)
 * Source: https://tailwindflex.com/@rajesh-pandey/divine-shree-ram-hero-section-tailwind-css-responsive-ui-for-devotional-hero-section-hero
 * Attribution: Créé par @rajesh-pandey sur TailwindFlex
 * License: Open Source (TailwindFlex community)
 */
import React from "react";

export function DivineShreeRamHeroSectionTailwindCssResponsiveUiForDevotionalHeroSectionHero() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<div class="relative w-screen h-screen overflow-hidden bg-gradient-to-br from-yellow-100 via-amber-200 to-orange-100 dark:from-gray-900 dark:via-gray-800 dark:to-black flex items-center justify-center px-6">
  <!-- Background aura -->
  <div class="absolute inset-0 bg-[url('https://i.ibb.co/9rZ2hRZ/ramji.png')] bg-contain bg-no-repeat bg-center opacity-10 lg:opacity-20"></div>

  <!-- Content Container -->
  <div class="relative z-10 text-center max-w-3xl space-y-6">
    <h1 class="text-5xl md:text-6xl lg:text-7xl font-extrabold tracking-tight font-serif text-yellow-900 dark:text-yellow-200 drop-shadow-xl animate-fade-in-up">
      जय श्री राम 🚩
    </h1>

    <p class="text-xl md:text-2xl text-gray-700 dark:text-gray-300 font-medium animate-fade-in-up delay-200">
      Embark on a divine journey of dharma, courage, and compassion. Inspired by the life of Lord Ram — the embodiment of virtue.
    </p>

    <div class="flex justify-center gap-4 pt-4 animate-fade-in-up delay-300">
      <a href="#learn-more" class="bg-yellow-500 hover:bg-yellow-600 text-white font-bold py-3 px-6 rounded-lg shadow-lg transition duration-300">
        Learn About Ramayana
      </a>
      <a href="#mantra" class="bg-white dark:bg-gray-700 dark:text-yellow-300 border border-yellow-400 hover:bg-yellow-100 text-yellow-700 font-semibold py-3 px-6 rounded-lg shadow-lg transition duration-300">
        Chant the Mantra
      </a>
    </div>
  </div>

  <!-- Custom animation -->
  <style>
    @keyframes fade-in-up {
      0% {
        opacity: 0;
        transform: translateY(30px);
      }
      100% {
        opacity: 1;
        transform: translateY(0);
      }
    }
    .animate-fade-in-up {
      animation: fade-in-up 1s ease forwards;
    }
    .delay-200 {
      animation-delay: 0.2s;
    }
    .delay-300 {
      animation-delay: 0.4s;
    }
  </style>
</div>" }} />
  );
}
